# Fibonacci Series and Factorial Program # Function to print Fibonacci series up to n def fibonacci(n): # First two numbers of Fibonacci series a = 0 b = 1 # Print heading print("Fibonacci series up to", n, ":") # Continue until a becomes greater than n while a <= n: # Print current Fibonacci number print(a, end=" ") # Calculate the next Fibonacci number a, b = b, a + b # Move to the next line print() # Function to calculate factorial of n def factorial(n): # Start result with 1 result = 1 # Multiply numbers from 1 to n for i in range(1, n + 1): result = result * i # Return the final result return result # Main function def main(): # Take input from the user n = int(input("Enter a number (N): ")) # Check if the number is negative if n < 0: print("Please enter a non-negative number.") return # Call Fibonacci function fibonacci(n) # Calculate and display factorial print("Factorial of", n, "is", factorial(n)) # Start the program if __name__ == "__main__": main()